$('#identity-open').onclick=()=>{identity();$('#identity-error').textContent='';$('#identity-secret').value='';$('#identity-dialog').showModal();};
$('#identity-form').onsubmit=e=>{e.preventDefault();const role=$('#identity-role').value,secret=$('#identity-secret').value;if(state.lockUntil>Date.now()){$('#identity-error').textContent='尝试过多，请30秒后再试。';return;}if(secret!==role+'-demo'){state.failedLogins++;if(state.failedLogins>=5){state.lockUntil=Date.now()+30000;state.failedLogins=0;}save();$('#identity-error').textContent='身份或演示口令错误';return;}state.session={role,expires:Date.now()+8*3600000};state.failedLogins=0;save();identity();$('#identity-dialog').close();G.audit('login',role);};
